const bar=document.getElementById('scroll-progress');
window.addEventListener('scroll',function(){
  var h=document.body.scrollHeight-window.innerHeight;
  bar.style.width=h?(window.scrollY/h*100)+'%':'0%';
});
const hdr=document.getElementById('site-header');
window.addEventListener('scroll',function(){
  hdr.classList.toggle('scrolled',window.scrollY>50);
});
document.getElementById('hamburger').addEventListener('click',function(){
  document.getElementById('mobile-nav').classList.toggle('open');
});
const fab=document.getElementById('fab');
const chat=document.getElementById('chat-widget');
window.addEventListener('scroll',function(){
  fab.classList.toggle('visible',window.scrollY>300);
});
fab.addEventListener('click',function(){ chat.classList.toggle('open'); });
document.getElementById('chat-close').addEventListener('click',function(){ chat.classList.remove('open'); });
document.getElementById('footer-year').textContent=new Date().getFullYear();
window.scrollTo({top:0,behavior:'instant'});
document.querySelectorAll('.faq-q').forEach(function(btn){
  btn.addEventListener('click',function(){
    var item=this.parentElement;
    document.querySelectorAll('.faq-item').forEach(function(i){ if(i!==item){ i.classList.remove('open'); } });
    item.classList.toggle('open');
  });
});
document.querySelectorAll('.share-btn').forEach(function(btn){
  btn.addEventListener('click',function(){
    var type=this.dataset.type;
    var url=encodeURIComponent(window.location.href);
    var title=encodeURIComponent(document.title);
    var w='';
    if(type==='wa') w='https://wa.me/?text='+title+'%20'+url;
    else if(type==='tw') w='https://twitter.com/intent/tweet?text='+title+'&url='+url;
    else if(type==='li') w='https://www.linkedin.com/sharing/share-offsite/?url='+url;
    if(w) window.open(w,'_blank','width=600,height=400');
  });
});
(function(){
  var prose=document.getElementById('article-prose');
  var list=document.getElementById('toc-list');
  if(!prose||!list) return;
  var hs=prose.querySelectorAll('h2,h3');
  if(hs.length<2){ document.getElementById('toc-container').style.display='none'; return; }
  hs.forEach(function(h){
    if(!h.id) h.id=h.textContent.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
    var li=document.createElement('li');
    if(h.tagName==='H3') li.classList.add('toc-h3');
    var a=document.createElement('a');
    a.href='#'+h.id;
    a.textContent=h.textContent;
    a.addEventListener('click',function(e){
      e.preventDefault();
      var target=document.getElementById(h.id);
      if(target) target.scrollIntoView({behavior:'smooth'});
    });
    li.appendChild(a);
    list.appendChild(li);
  });
  var obs=new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        list.querySelectorAll('a').forEach(function(a){ a.classList.remove('active'); });
        var ac=list.querySelector('a[href="#'+entry.target.id+'"]');
        if(ac) ac.classList.add('active');
      }
    });
  },{rootMargin:'-80px 0px -75% 0px'});
  hs.forEach(function(h){ obs.observe(h); });
})();
